39	function getGitCommit(): string {
40	  try {
41	    const out = spawnSync('git', ['rev-parse', '--short', 'HEAD'], { encoding: 'utf8', stdio: 'pipe' });
42	    if (out.status !== 0) throw new Error(out.stderr?.toString() ?? 'git failed');
43	    return (out.stdout?.toString() ?? '').trim() || 'unknown';
