187	function captureMetrics(
188	  ev: RawEvent,
189	  setters: {
190	    toolCalls: (updater: (v: number) => number) => void;
191	    toolErrors: (updater: (v: number) => number) => void;
192	    retries: (updater: (v: number) => number) => void;
193	    compactions: (updater: (v: number) => number) => void;
194	    inputTokens: (updater: (v: number) => number) => void;
195	    outputTokens: (updater: (v: number) => number) => void;
196	    totalTokens: (updater: (v: number) => number) => void;
197	    stopReason: (v: string | null) => void;
198	    failureReason: (v: string | null) => void;
199	    turns: (updater: (v: number) => number) => void;
200	    resultSubtype: (v: string | null) => void;
201	  },
202	) {
203	  switch (ev.type) {
204	    case 'thinking_start':
205	      setters.turns((v) => v + 1);
206	      break;
207	    case 'tool_start':
208	      setters.toolCalls((v) => v + 1);
209	      break;
210	    case 'tool_end': {
211	      const end = ev as { isError?: boolean };
212	      if (end.isError) setters.toolErrors((v) => v + 1);
213	      break;
214	    }
215	    case 'retry':
216	      setters.retries((v) => v + 1);
217	      break;
218	    case 'context.apply_compaction':
219	      setters.compactions((v) => v + 1);
220	      break;
221	    case 'usage': {
222	      const u = ev as { totalTokens?: number; billedDelta?: number };
223	      if (typeof u.totalTokens === 'number') setters.totalTokens((v) => u.totalTokens!);
224	      if (typeof u.billedDelta === 'number') setters.outputTokens((v) => v + u.billedDelta!);
225	      break;
226	    }
227	    case 'model.usage': {
228	      const mu = ev as {
229	        totalTokens?: number;
230	        inputTokens?: number;
231	        outputTokens?: number;
232	        cacheReadTokens?: number;
233	        cacheCreationTokens?: number;
234	      };
235	      if (typeof mu.totalTokens === 'number') setters.totalTokens((v) => mu.totalTokens!);
236	      if (typeof mu.inputTokens === 'number') setters.inputTokens((v) => v + mu.inputTokens!);
237	      if (typeof mu.outputTokens === 'number') setters.outputTokens((v) => v + mu.outputTokens!);
238	      break;
239	    }
240	    case 'result':
241	      setters.resultSubtype((ev as { subtype?: string }).subtype ?? null);
242	      break;
243	    case 'error':
244	      setters.failureReason((ev as { message?: string }).message ?? 'error');
245	      setters.resultSubtype('error');
246	      break;
247	    case 'turn.issue': {
248	      const issue = ev as { kind?: string; message?: string };
249	      if (issue.kind === 'empty' || issue.kind === 'error') {
250	        setters.failureReason(issue.message ?? issue.kind ?? 'turn.issue');
251	      }
252	      break;
253	    }
254	    default:
