338	async function executeCheck(check: { type: string; command?: string; path?: string; pattern?: string; expect?: Record<string, unknown> }, repoDir: string): Promise<boolean> {
339	  switch (check.type) {
340	    case 'test': {
341	      try {
342	        const { execSync } = await import('node:child_process');
343	        const output = execSync(check.command ?? '', {
344	          cwd: repoDir,
345	          encoding: 'utf8',
346	          stdio: 'pipe',
347	        });
348	        if (check.expect?.exit_code !== undefined && check.expect.exit_code !== 0) {
349	          return false;
350	        }
351	        if (check.expect?.stdout_contains && !output.includes(check.expect.stdout_contains as string)) {
352	          return false;
353	        }
354	        if (check.expect?.stderr_not_contains && output.toLowerCase().includes((check.expect.stderr_not_contains as string).toLowerCase())) {
355	          return false;
356	        }
357	        return true;
358	      } catch {
359	        return false;
360	      }
361	    }
362	    case 'file_contains': {
363	      const filePath = join(repoDir, check.path ?? '');
364	      if (!existsSync(filePath)) return false;
365	      const content = readFileSync(filePath, 'utf8');
366	      const regex = check.pattern ? new RegExp(check.pattern) : null;
367	      return regex ? regex.test(content) : false;
368	    }
369	    case 'file_not_contains': {
370	      const filePath = join(repoDir, check.path ?? '');
371	      if (!existsSync(filePath)) return true;
372	      const content = readFileSync(filePath, 'utf8');
373	      const regex = check.pattern ? new RegExp(check.pattern) : null;
374	      return regex ? !regex.test(content) : true;
375	    }
376	    case 'file_exists': {
377	      const filePath = join(repoDir, check.path ?? '');
378	      return existsSync(filePath);
379	    }
380	    case 'command': {
381	      try {
382	        const { execSync } = await import('node:child_process');
383	        const output = execSync(check.command ?? '', {
384	          cwd: repoDir,
385	          encoding: 'utf8',
386	          stdio: 'pipe',
387	        });
388	        if (check.expect?.exit_code !== undefined) {
389	          // Can't easily check exit code here, assume success if no throw
390	        }
391	        if (check.expect?.stdout_contains && !output.includes(check.expect.stdout_contains as string)) {
392	          return false;
393	        }
394	        return true;
395	      } catch {
396	        return false;
397	      }
