213	  let currentKey = '';
214	  let inSetup = false;
215	  let inVerify = false;
216	  let currentCheck: any = null;
217	  let currentExpect: any = null;
218	
219	  for (const line of lines) {
220	    if (line.startsWith('setup: |') || line.startsWith('setup: >')) {
221	      inSetup = true;
222	      inVerify = false;
223	      continue;
224	    }
225	    if (line.startsWith('verify:')) {
226	      inSetup = false;
227	      inVerify = true;
228	      continue;
229	    }
230	    if (inSetup) {
231	      task.setup += line + '\n';
232	      continue;
233	    }
234	    if (inVerify) {
235	      if (line.match(/^\s*- type:/)) {
236	        if (currentCheck) task.verify.push(currentCheck);
237	        currentCheck = { type: line.match(/type:\s*(\w+)/)?.[1] ?? 'command', expect: {} };
238	      } else if (line.match(/^\s+command:/)) {
239	        currentCheck.command = line.match(/command:\s*"(.+)"/)?.[1] ?? line.match(/command:\s*(.+)/)?.[1] ?? '';
240	      } else if (line.match(/^\s+path:/)) {
241	        currentCheck.path = line.match(/path:\s*"(.+)"/)?.[1] ?? line.match(/path:\s*(.+)/)?.[1] ?? '';
242	      } else if (line.match(/^\s+pattern:/)) {
243	        currentCheck.pattern = line.match(/pattern:\s*"(.+)"/)?.[1] ?? line.match(/pattern:\s*(.+)/)?.[1] ?? '';
244	      } else if (line.match(/^\s+exit_code:/)) {
245	        currentCheck.expect = currentCheck.expect ?? {};
246	        currentCheck.expect.exit_code = parseInt(line.match(/exit_code:\s*(\d+)/)?.[1] ?? '0', 10);
247	      } else if (line.match(/^\s+stdout_contains:/)) {
248	        currentCheck.expect = currentCheck.expect ?? {};
249	        currentCheck.expect.stdout_contains = line.match(/stdout_contains:\s*"(.+)"/)?.[1] ?? line.match(/stdout_contains:\s*(.+)/)?.[1] ?? '';
250	      } else if (line.match(/^\s+stderr_not_contains:/)) {
251	        currentCheck.expect = currentCheck.expect ?? {};
252	        currentCheck.expect.stderr_not_contains = line.match(/stderr_not_contains:\s*"(.+)"/)?.[1] ?? line.match(/stderr_not_contains:\s*(.+)/)?.[1] ?? '';
253	      }
