310	  if (/^\d+$/.test(value)) return parseInt(value, 10);
311	  if (/^\d+\.\d+$/.test(value)) return parseFloat(value);
312	  if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
313	    return value.slice(1, -1);
314	  }
